//! Finite source-note derivations and unjudged spacing composition regressions.
use klem::dictionary::{Dictionary, DictionarySession, SqliteDictionary, import_krdict};
use klem::{Analysis, Lemmatizer, Session, WordAnalysis};
use serde_json::Value;
use std::{path::PathBuf, sync::Arc};
use unicode_normalization::UnicodeNormalization;
#[path = "../tools/validity.rs"]
mod validity;

fn matches(a: &Analysis, j: &validity::Judgment) -> bool {
    a.lemmas.iter().map(|l| &l.text).eq(j.lemmas.iter())
        && a.lemmas
            .iter()
            .map(|l| l.kind)
            .eq(j.lemma_kinds.as_ref().unwrap().iter().copied())
        && a.morphemes
            .iter()
            .map(|m| &m.form)
            .eq(j.morphemes.as_ref().unwrap().iter())
        && a.morphemes
            .iter()
            .map(|m| m.kind)
            .eq(j.morpheme_kinds.as_ref().unwrap().iter().copied())
        && j.required_rules
            .as_ref()
            .unwrap()
            .iter()
            .all(|r| a.rules.contains(r))
}
fn suite() -> validity::Suite {
    serde_json::from_str(include_str!(
        "fixtures/literary-question-go-boundaries.json"
    ))
    .unwrap()
}
#[test]
fn individual_boundary_ids_check_19_required_and_four_path_specific_exclusions() {
    let report = validity::evaluate(&suite()).unwrap();
    assert!(report.passed(), "{:?}", report.violations);
    assert_eq!(report.cases, 23);
    assert_eq!(report.required_total, 19);
    assert_eq!(report.forbidden_total, 4);
}
#[test]
fn boundary_paths_keep_unicode_earlier_order_spelling_recovery_and_explanations() {
    let before: Value = serde_json::from_str(include_str!(
        "fixtures/literary-question-go-boundary-before.json"
    ))
    .unwrap();
    let engine = Lemmatizer::new();
    for case in suite().cases {
        let old: WordAnalysis = serde_json::from_value(before[&case.surface].clone()).unwrap();
        let raw = engine.analyze_word(&case.surface).unwrap();
        assert_eq!(
            raw,
            engine
                .analyze_word(&case.surface.nfd().collect::<String>())
                .unwrap()
        );
        assert_eq!(
            raw.analyses
                .iter()
                .filter(|a| old.analyses.contains(a))
                .cloned()
                .collect::<Vec<_>>(),
            old.analyses
        );
        for j in case.judgments {
            for a in raw.analyses.iter().filter(|a| matches(a, &j)) {
                assert!(a.breakdown().is_some(), "{}: {a:?}", case.id);
                assert!(a.rules.iter().all(|r| klem::rule_explanation(r).is_some()));
                if case.id.ends_with("bieup-descriptive") || case.id.ends_with("bieup-cold") {
                    assert!(a.rules.iter().any(|r| r == "irregular.bieup"));
                    assert!(!a.spelling_paths.is_empty());
                }
                if case.id.ends_with("hieut-demonstrative") || case.id.ends_with("hieut-color") {
                    assert!(a.rules.iter().any(|r| r == "irregular.hieut"));
                    assert!(!a.spelling_paths.is_empty());
                }
            }
        }
    }
}
struct Cleanup(PathBuf);
impl Drop for Cleanup {
    fn drop(&mut self) {
        let _ = std::fs::remove_file(&self.0);
    }
}
fn dictionary(name: &str) -> (SqliteDictionary, Cleanup) {
    let p = std::env::temp_dir().join(format!(
        "klem-question-go-boundaries-{name}-{}.db",
        std::process::id()
    ));
    assert!(!p.exists());
    let cleanup = Cleanup(p.clone());
    import_krdict(
        &[PathBuf::from(
            "tests/fixtures/literary-question-go-spelling-spacing-english.json",
        )],
        &p,
        "literary-question-go-boundaries",
    )
    .unwrap();
    (SqliteDictionary::open(p).unwrap(), cleanup)
}
#[test]
fn all_128_original_entries_and_same_head_homonyms_survive_the_real_importer() {
    let (db, _cleanup) = dictionary("native");
    let native: Value = serde_json::from_str(include_str!(
        "fixtures/literary-question-go-spelling-spacing-native.json"
    ))
    .unwrap();
    assert_eq!(native.as_object().unwrap().len(), 128);
    for (id, expected) in native.as_object().unwrap() {
        let mut english = expected.clone();
        for sense in english["senses"].as_array_mut().unwrap() {
            sense["translations"]
                .as_array_mut()
                .unwrap()
                .retain(|t| t["language"] == "영어");
        }
        assert_eq!(
            serde_json::to_value(db.entry(id).unwrap().unwrap()).unwrap(),
            english
        );
        let e = db.entry(id).unwrap().unwrap();
        assert!(
            db.lookup(&e.summary.headword)
                .unwrap()
                .iter()
                .any(|s| s.id == *id)
        );
    }
}
#[test]
fn new_spacing_hypotheses_keep_native_owners_unicode_and_original_boundaries() {
    // These are conditional raw hypotheses, not judgments about the novel's
    // intended reading. Original complete-line captures remain unjudged.
    let (db, _cleanup) = dictionary("spacing");
    let mut dict = DictionarySession::new(&db, 1024);
    let engine = Arc::new(Lemmatizer::new());
    let mut words = Session::new(engine, 1024);
    for (whole, left, right, head) in [
        ("돌아갔는고", "돌아", "갔는고", "가다"),
        ("살아왔는고", "살아", "왔는고", "오다"),
    ] {
        for encoding in [false, true] {
            let original = if encoding {
                whole.nfd().collect::<String>()
            } else {
                whole.to_owned()
            };
            let lhs = if encoding {
                left.nfd().collect::<String>()
            } else {
                left.to_owned()
            };
            let rhs = if encoding {
                right.nfd().collect::<String>()
            } else {
                right.to_owned()
            };
            let value = serde_json::to_value(
                klem::spacing::suggest(
                    &mut words,
                    &mut dict,
                    &original,
                    37,
                    klem::spacing::SpacingLimits::default(),
                )
                .unwrap(),
            )
            .unwrap();
            assert_eq!(value["complete"], true);
            let alternative = value["alternatives"]
                .as_array()
                .unwrap()
                .iter()
                .find(|h| h["spaced"] == format!("{lhs} {rhs}"))
                .unwrap();
            assert_eq!(
                alternative["inserted_at"],
                serde_json::json!([37 + lhs.len()])
            );
            assert_eq!(alternative["records"][0]["surface"], lhs);
            assert_eq!(alternative["records"][1]["surface"], rhs);
            assert_eq!(
                alternative["records"][0]["span"],
                serde_json::json!({"start":37,"end":37+lhs.len()})
            );
            assert_eq!(
                alternative["records"][1]["span"],
                serde_json::json!({"start":37+lhs.len(),"end":37+original.len()})
            );
            let segment = &alternative["records"][1];
            assert!(
                segment["analysis"]["analyses"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .any(|a| a["lemmas"][0]["text"] == head
                        && a["rules"]
                            .as_array()
                            .unwrap()
                            .iter()
                            .any(|r| r == "ending.literary_question_go"))
            );
        }
    }
}

tests/literary_question_go_native.rs.text:
use klem::{Analysis, Lemmatizer};
use unicode_normalization::UnicodeNormalization;

#[path = "../tools/validity.rs"]
mod validity;

#[test]
fn all_39_source_occurrences_have_individual_required_judgments() {
    let suite: validity::Suite =
        serde_json::from_str(include_str!("fixtures/literary-question-go-validity.json")).unwrap();
    let report = validity::evaluate(&suite).unwrap();
    assert!(report.passed(), "{:?}", report.violations);
    assert_eq!(report.cases, 39);
    assert_eq!(report.required_total, 39);
}

fn expected_path(a: &Analysis, expected: &serde_json::Value) -> bool {
    let value = serde_json::to_value(a).unwrap();
    value["lemmas"]
        .as_array()
        .unwrap()
        .iter()
        .map(|l| &l["text"])
        .eq(expected["lemmas"].as_array().unwrap())
        && value["lemmas"]
            .as_array()
            .unwrap()
            .iter()
            .map(|l| &l["kind"])
            .eq(expected["lemma_kinds"].as_array().unwrap())
        && value["morphemes"]
            .as_array()
            .unwrap()
            .iter()
            .map(|m| &m["form"])
            .eq(expected["morphemes"].as_array().unwrap())
        && value["morphemes"]
            .as_array()
            .unwrap()
            .iter()
            .map(|m| &m["kind"])
            .eq(expected["morpheme_kinds"].as_array().unwrap())
        && a.rules.iter().any(|r| r == "ending.literary_question_go")
}

struct Cleanup(std::path::PathBuf);
impl Drop for Cleanup {
    fn drop(&mut self) {
        let _ = std::fs::remove_file(&self.0);
    }
}

fn dictionary(name: &str) -> (klem::dictionary::SqliteDictionary, Cleanup) {
    use klem::dictionary::{SqliteDictionary, import_krdict};
    let path = std::env::temp_dir().join(format!(
        "klem-literary-question-go-{name}-{}.db",
        std::process::id()
    ));
    assert!(!path.exists());
    let cleanup = Cleanup(path.clone());
    import_krdict(
        &[std::path::PathBuf::from(
            "tests/fixtures/literary-question-go-english.json",
        )],
        &path,
        "literary-question-go-source",
    )
    .unwrap();
    (SqliteDictionary::open(path).unwrap(), cleanup)
}

#[test]
fn all_original_paths_survive_every_mode_without_certifying_the_conflicting_note() {
    use klem::dictionary::{DictionaryFilter, DictionarySession};
    let engine = Lemmatizer::new();
    let cases: Vec<serde_json::Value> = serde_json::from_str(include_str!(
        "fixtures/literary-question-go-original-cases.json"
    ))
    .unwrap();
    let (db, _cleanup) = dictionary("original-modes");
    let mut session = DictionarySession::new(&db, 1024);
    for case in cases {
        let before: klem::WordAnalysis = serde_json::from_value(case["before"].clone()).unwrap();
        let word = case["surface"].as_str().unwrap();
        for text in [word.to_string(), word.nfd().collect()] {
            let raw = engine.analyze_word(&text).unwrap();
            assert_eq!(
                raw.analyses
                    .iter()
                    .filter(|a| before.analyses.contains(a))
                    .cloned()
                    .collect::<Vec<_>>(),
                before.analyses,
                "{} lost earlier candidates",
                case["id"]
            );
            let target = raw
                .analyses
                .iter()
                .find(|a| expected_path(a, &case["expected"]))
                .unwrap();
            let annotation = session.annotate(&raw).unwrap();
            if case["source_occurrence"]["source"] == "krdict:73892" {
                assert_eq!(
                    serde_json::to_value(annotation.assess(target)).unwrap()["status"],
                    "unknown",
                    "{}",
                    case["id"]
                );
            }
            for mode in [DictionaryFilter::Headword, DictionaryFilter::Compatible] {
                let mut filtered = raw.clone();
                let mut annotation = annotation.clone();
                annotation.filter(&mut filtered, mode);
                assert!(
                    filtered
                        .analyses
                        .iter()
                        .any(|a| expected_path(a, &case["expected"])),
                    "{} {mode:?}: {:?}",
                    case["id"],
                    filtered
                );
            }
        }
    }
}

#[test]
fn all_native_fields_and_same_head_homonyms_survive_the_production_importer() {
    use klem::dictionary::Dictionary;
    let native: serde_json::Value =
        serde_json::from_str(include_str!("fixtures/literary-question-go-native.json")).unwrap();
    assert_eq!(native.as_object().unwrap().len(), 115);
    let (db, _cleanup) = dictionary("native");
    for (id, expected) in native.as_object().unwrap() {
        let actual = serde_json::to_value(db.entry(id).unwrap().unwrap()).unwrap();
        let mut projected = expected.clone();
        for sense in projected["senses"].as_array_mut().unwrap() {
            sense["translations"]
                .as_array_mut()
                .unwrap()
                .retain(|t| t["language"] == "영어");
        }
        assert_eq!(actual, projected, "{id}");
        let ids: Vec<_> = db
            .lookup(expected["headword"].as_str().unwrap())
            .unwrap()
            .into_iter()
            .map(|entry| entry.id)
            .collect();
        for (other, value) in native.as_object().unwrap() {
            if value["headword"] == expected["headword"] {
                assert!(ids.contains(other), "{id} lost {other}");
            }
        }
    }
}

#[test]
fn individual_conditional_modes_use_each_native_owner_and_preserve_unknowns() {
    use klem::dictionary::{DictionaryFilter, DictionarySession};
    let matrix: serde_json::Value = serde_json::from_str(include_str!(
        "fixtures/literary-question-go-mode-scope.json"
    ))
    .unwrap();
    let cases = matrix["cases"].as_array().unwrap();
    assert_eq!(cases.len(), 16);
    let mut ids = std::collections::HashSet::new();
    let engine = Lemmatizer::new();
    let (db, _cleanup) = dictionary("conditional-modes");
    let mut session = DictionarySession::new(&db, 1024);
    for case in cases {
        assert!(ids.insert(case["id"].as_str().unwrap()));
        assert_eq!(case["contextual_verdict"], "unjudged");
        let word = case["surface"].as_str().unwrap();
        for text in [word.to_string(), word.nfd().collect()] {
            let raw = engine.analyze_word(&text).unwrap();
            let annotation = session.annotate(&raw).unwrap();
            let targets: Vec<_> = raw
                .analyses
                .iter()
                .filter(|a| expected_path(a, &case["expected"]))
                .collect();
            assert_eq!(
                !targets.is_empty(),
                case["expected_presence"]["raw"].as_bool().unwrap(),
                "{}",
                case["id"]
            );
            for target in targets {
                let assessment = serde_json::to_value(annotation.assess(target)).unwrap();
                for expected in case["expected_entry_statuses"].as_array().unwrap() {
                    let slot = expected["lemma"].as_u64().unwrap() as usize;
                    let actual = assessment["lemmas"][slot]["entries"]
                        .as_array()
                        .unwrap()
                        .iter()
                        .find(|e| e["id"] == expected["id"])
                        .unwrap();
                    assert_eq!(
                        actual["status"], expected["status"],
                        "{}: {}",
                        case["id"], expected["id"]
                    );
                }
            }
            for (mode, key) in [
                (DictionaryFilter::Headword, "headword"),
                (DictionaryFilter::Compatible, "compatible"),
            ] {
                let mut filtered = raw.clone();
                let mut annotation = annotation.clone();
                annotation.filter(&mut filtered, mode);
                assert_eq!(
                    filtered
                        .analyses
                        .iter()
                        .any(|a| expected_path(a, &case["expected"])),
                    case["expected_presence"][key].as_bool().unwrap(),
                    "{} {key}",
                    case["id"]
                );
            }
        }
    }
}
